import { Component, Prop, Vue, Watch } from 'vue-property-decorator';
import { UserPreferenceValue } from '../../types';
import { UserPreferences } from '../../user-preferences';

@Component
export class PersistentSettingComponent<T extends UserPreferenceValue> extends Vue {
    @Prop({
        type: String,
        required: true
    })
    public prefKey!: string;

    @Prop({
        required: true
    })
    public default!: T;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public isGlobal!: boolean;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public isSubGame!: boolean;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public isMisc!: boolean;

    public value: T = UserPreferences.getPreference(this.prefKey, this.default, this.isMisc, this.isGlobal);

    @Watch('value')
    protected onValueChange(value: T) {
        UserPreferences.setPreference(this.prefKey, value, this.isMisc, this.isGlobal, this.isSubGame);
    }
}